?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cambiar contraseña — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f3f6fa;font-family:Manrope,Arial,sans-serif;color:#172033;padding:18px}.box{width:min(420px,100%);background:#fff;border-radius:18px;padding:24px;box-shadow:0 12px 35px #0f172a18}h1{margin:0 0 8px;font-size:26px}.sub{color:#64748b;font-size:13px;margin-bottom:20px}.field{margin:14px 0}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:6px}.field input{width:100%;padding:12px;border:1px solid #cbd5e1;border-radius:10px;font-size:16px}.btn{width:100%;border:0;border-radius:10px;background:#123b5d;color:#fff;padding:13px;font-weight:800;cursor:pointer;margin-top:8px}.msg{display:none;margin:0 0 12px;padding:10px;border-radius:9px;background:#fee2e2;color:#991b1b;font-size:13px}</style></head><body><main class="box"><h1>Nueva contraseña</h1><div class="sub"><?=!empty($me['debe_cambiar_password'])?'Por seguridad debes cambiar la contraseña temporal antes de continuar.':'Actualiza tu contraseña de acceso.'?></div><div id="msg" class="msg"></div><form id="form"><div class="field"><label>Contraseña actual</label><input id="actual" type="password" autocomplete="current-password" required></div><div class="field"><label>Nueva contraseña</label><input id="nueva" type="password" minlength="8" autocomplete="new-password" required></div><div class="field"><label>Repetir nueva contraseña</label><input id="repetir" type="password" minlength="8" autocomplete="new-password" required></div><button class="btn">Guardar contraseña</button></form></main><script>const f=document.getElementById('form'),m=document.getElementById('msg');f.onsubmit=async e=>{e.preventDefault();m.style.display='none';if(nueva.value!==repetir.value){m.textContent='Las contraseñas no coinciden';m.style.display='block';return}const r=await fetch('/api/cambiar-password.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actual:actual.value,nueva:nueva.value})});const d=await r.json();if(!r.ok||!d.ok){m.textContent=d.error||'No se pudo cambiar la contraseña';m.style.display='block';return}location.href=d.redirect||'/'};</script></body></html>